import express from 'express';

const PREMIUM_CUSTOMER_VIEW = Buffer.from('', 'base64').toString('utf8');
const previousSend = express.response.send;

express.response.send = function premiumCustomerViewPatch(body) {
  try {
    const requestPath = this.req?.path || this.req?.url || '';
    if (typeof body === 'string' && requestPath.startsWith('/app.js')) {
      const start = body.indexOf('async function showCustomer(id){');
      const end = body.indexOf('\n\nfunction classicLoanGuarantor', start);
      if (start !== -1 && end !== -1) {
        body = body.slice(0, start) + PREMIUM_CUSTOMER_VIEW + body.slice(end);
      }
    }
  } catch (_) {}

  return previousSend.call(this, body);
};
